/**
 * General-purpose connection request/response types for the Akita Connect protocol.
 *
 * These types define the payloads sent over a WebRTC data channel after a
 * liquid:// URI-based connection is established between two peers.
 */
/** Parsed liquid:// connect URI */
export interface AkitaConnectUri {
    /** Signaling server origin (e.g. "signal.akita.community") */
    origin: string;
    /** Session request ID (UUID) */
    requestId: string;
    /** Protocol version. Omitted by legacy agent-install links. */
    v?: number;
    /**
     * One-time base64url secret used to authenticate the WebRTC transcript.
     * The signaling service only receives requestId and never needs this value.
     */
    secret?: string;
}
export type AkitaConnectNetwork = 'localnet' | 'testnet' | 'mainnet';
export type TransactionPreviewPolicy = 'never' | 'optional' | 'required';
export type SerializedAllowance = {
    asset: string;
    type: 'flat';
    amount: string;
    useRounds?: boolean;
} | {
    asset: string;
    type: 'window';
    amount: string;
    interval: string;
    useRounds?: boolean;
} | {
    asset: string;
    type: 'drip';
    rate: string;
    max: string;
    interval: string;
    useRounds?: boolean;
};
export interface SerializedMethodDefinition {
    /** 4-byte ABI method selector as hex string (e.g. "a1b2c3d4") */
    name: string;
    cooldown: string;
}
export interface AgentInstallPlugin {
    /** Plugin identifier (sdkKey from NetworkAppIds, e.g. "payPlugin") */
    id: string;
    /** Whether the wallet owner covers transaction fees */
    coverFees?: boolean;
    /** Method cooldown in seconds (default 0) */
    cooldown?: string;
    /**
     * Spending allowances for this plugin.
     * @deprecated Use top-level `AgentInstallRequest.allowances` instead (v2).
     * Kept for backward compatibility with v1 requests.
     */
    allowances?: SerializedAllowance[];
    /** Method restrictions */
    methods?: SerializedMethodDefinition[];
}
export interface AgentInstallRequest {
    type: 'agent-install';
    v: 1 | 2;
    agent: {
        name: string;
        address: string;
    };
    network: AkitaConnectNetwork;
    escrowName: string;
    /** When true, the app sends 4.352 ALGO to the agent address for MBR */
    newAgentAccount: boolean;
    plugins: AgentInstallPlugin[];
    /**
     * Escrow-level spending allowances (v2).
     * Allowances are keyed on-chain by `{escrow, asset}`, so they belong at
     * the escrow level rather than per-plugin. For v1 requests, allowances
     * are read from individual `AgentInstallPlugin.allowances` entries.
     */
    allowances?: SerializedAllowance[];
}
export interface DappIdentity {
    name: string;
    /** Browser origin that initiated the request, including scheme. */
    origin: string;
    iconUrl?: string;
    description?: string;
}
export interface WalletConnectPluginRequest {
    /** SDK deployment key, for example `subscriptionsPlugin`. */
    id: string;
    /** A required plugin aborts the whole connection when it cannot be granted. */
    required: boolean;
    /** Expected deployment app ID. Prevents a display name from selecting another app. */
    appId: string;
    /** Optional deployment revision advertised by the dApp. */
    revision?: string;
    coverFees?: boolean;
    methods?: SerializedMethodDefinition[];
    /** Absolute unix timestamp or round depending on useRounds. */
    lastValid?: string;
    useRounds?: boolean;
}
export interface WalletConnectPasskeyRequest {
    required: true;
    provider: 'akita-hyperspace';
    /** Must be the effective domain of dapp.origin. */
    rpId: string;
    userName: string;
    userDisplayName: string;
    /** base64url WebAuthn user handle, generated by the dApp for this session. */
    userHandle: string;
    /** base64url registration challenge generated by the dApp. */
    challenge: string;
    /** The dApp's supported/default preview behavior; the wallet owner chooses the final policy. */
    transactionPreview: TransactionPreviewPolicy;
}
export interface WalletConnectRequest {
    type: 'wallet-connect';
    v: 3;
    network: AkitaConnectNetwork;
    dapp: DappIdentity;
    /** Optional address hint when repairing a previously configured session. */
    preferredAccount?: string;
    plugins: WalletConnectPluginRequest[];
    passkey: WalletConnectPasskeyRequest;
    /** Requested session expiry as a unix timestamp. */
    expiresAt: number;
}
export interface WalletConnectFinalizeRequest {
    type: 'wallet-connect-finalize';
    v: 3;
    sessionId: string;
    account: string;
    credential: {
        id: string;
        rpId: string;
        publicKeyX: string;
        publicKeyY: string;
        /** Address of the canonical Akita P-256 LogicSig for this public key. */
        caller: string;
        provider: 'akita-hyperspace';
    };
    transactionPreview: TransactionPreviewPolicy;
}
export interface WalletConnectRevokeRequest {
    type: 'wallet-connect-revoke';
    v: 3;
    sessionId: string;
}
/**
 * Live session key connection. The caller is a 2-of-2 multisig of a
 * non-extractable Ed25519 key held by the dApp page and an Ed25519 key held by
 * the dApp server, so the server can act in the background only while the
 * page is open to co-sign.
 */
export interface SessionKeyConnectRequest {
    type: 'session-key-connect';
    v: 1;
    network: AkitaConnectNetwork;
    dapp: DappIdentity;
    preferredAccount?: string;
    /** Address of the page's non-extractable Ed25519 key. First multisig signer. */
    browserKey: string;
    /** Address of the dApp server's Ed25519 key. Second multisig signer. */
    serverKey: string;
    /** Escrow the session's plugins spend from. Created when missing. */
    escrowName: string;
    plugins: WalletConnectPluginRequest[];
    /** Spending limits on the escrow, keyed on-chain by `{escrow, asset}`. */
    allowances?: SerializedAllowance[];
    /** Requested session expiry as a unix timestamp. */
    expiresAt: number;
}
export interface SessionKeyRevokeRequest {
    type: 'session-key-revoke';
    v: 1;
    sessionId: string;
}
export type ConnectRequest = AgentInstallRequest | WalletConnectRequest | WalletConnectFinalizeRequest | WalletConnectRevokeRequest | SessionKeyConnectRequest | SessionKeyRevokeRequest;
export interface AgentInstallResponse {
    type: 'agent-install';
    success: true;
    walletAppId: string;
    escrowAddress: string;
    network: string;
}
export interface WalletConnectAccount {
    /** Controlled account exposed to use-wallet and used for subscription ownership. */
    address: string;
    walletAppId: string;
    name?: string;
}
export interface WalletConnectApprovedResponse {
    type: 'wallet-connect-approved';
    success: true;
    sessionId: string;
    account: WalletConnectAccount;
    approvedPlugins: WalletConnectPluginRequest[];
    transactionPreview: TransactionPreviewPolicy;
}
export interface WalletConnectReadyResponse {
    type: 'wallet-connect-ready';
    success: true;
    session: WalletConnectSession;
}
export interface WalletConnectRevokedResponse {
    type: 'wallet-connect-revoked';
    success: true;
    sessionId: string;
}
export interface WalletConnectSession {
    v: 3;
    sessionId: string;
    network: AkitaConnectNetwork;
    dapp: DappIdentity;
    account: WalletConnectAccount;
    credential: WalletConnectFinalizeRequest['credential'];
    plugins: WalletConnectPluginRequest[];
    transactionPreview: TransactionPreviewPolicy;
    /** Bearer-scoped handoff used by the Akita AutoFill extension. */
    nativePreview?: {
        endpoint: string;
        token: string;
    };
    createdAt: number;
    expiresAt: number;
}
export interface SessionKeySession {
    v: 1;
    kind: 'session-key';
    sessionId: string;
    network: AkitaConnectNetwork;
    dapp: DappIdentity;
    account: WalletConnectAccount;
    /** The 2-of-2 multisig address granted the plugins. */
    caller: string;
    browserKey: string;
    serverKey: string;
    escrowName: string;
    plugins: WalletConnectPluginRequest[];
    allowances: SerializedAllowance[];
    createdAt: number;
    expiresAt: number;
}
export interface SessionKeyConnectedResponse {
    type: 'session-key-connected';
    success: true;
    session: SessionKeySession;
}
export interface SessionKeyRevokedResponse {
    type: 'session-key-revoked';
    success: true;
    sessionId: string;
}
export interface ConnectErrorResponse {
    type: 'error';
    success: false;
    message: string;
}
export type ConnectResponse = AgentInstallResponse | WalletConnectApprovedResponse | WalletConnectReadyResponse | WalletConnectRevokedResponse | SessionKeyConnectedResponse | SessionKeyRevokedResponse | ConnectErrorResponse;
/**
 * Authenticated wrapper for v3 messages. `mac` is HMAC-SHA256 over the other
 * fields in canonical key order using the secret embedded in the scanned URI.
 */
export interface AuthenticatedConnectEnvelope<T extends ConnectRequest | ConnectResponse = ConnectRequest | ConnectResponse> {
    v: 3;
    requestId: string;
    nonce: string;
    issuedAt: number;
    expiresAt: number;
    payload: T;
    mac: string;
}
